__NUXT_JSONP__("/think-tanks/eventos/es_necesario_que_los_think_tanks_de_la_region_trabajen_de_manera_coordinada_para_atender_problematicas_comunes", (function(a,b,c,d,e,f,g,h,i,j,k,l){return {data:[{post:{slug:"es_necesario_que_los_think_tanks_de_la_region_trabajen_de_manera_coordinada_para_atender_problematicas_comunes",title:"Es necesario que los think tanks de la región  trabajen de manera coordinada para atender problemáticas comunes",date:"2023-11-29T16:41:26.904Z",img:"https:\u002F\u002Fucarecdn.com\u002F0988310a-d989-464d-8a17-2268dfa9d84e\u002F","img-alt":"Liliana Alvarado, Dalia Toledo Ethos",autor:"Ethos",category:"think-tanks",extracto:" Liliana Alvarado, directora de Ethos, y Dalia Toledo, directora de Finanzas Públicas y Anticorrupción, participaron en el encuentro «La integración centroamericana: estado de situación y perspectivas», que se llevó a cabo en Guatemala.",toc:[],body:{type:"root",children:[{type:b,tag:c,props:{},children:[{type:a,value:"Ethos Innovación en Políticas Públicas estuvo presente en el encuentro «La integración centroamericana: estado de situación y perspectivas», organizado por la "},{type:b,tag:g,props:{href:"http:\u002F\u002Fwww.asies.org.gt\u002F",rel:[h,i,j],target:k},children:[{type:a,value:"Asociación de Investigación y Estudios Sociales"}]},{type:a,value:" (ASIES, de Guatemala) y "},{type:b,tag:g,props:{href:"https:\u002F\u002Fwww.fundaungo.org.sv\u002F",rel:[h,i,j],target:k},children:[{type:a,value:"Funaungo"}]},{type:a,value:" (de El Salvador), que se realizó en Guatemala. Acudieron Liliana Alvarado, directora general, y Dalia Toledo, directora de Finanzas Públicas y Anticorrupción de Ethos."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Al hablar de los retos que tienen los "},{type:b,tag:e,props:{},children:[{type:a,value:f}]},{type:a,value:" en la región, Liliana Alvarado puso sobre la mesa temas como el auge y normalización de las fake news, la tendencia de los gobiernos de despreciar la información basada en evidencia y el trabajo de la sociedad civil, la falta de diálogo con el gobierno, así como el aumento de la corrupción."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Asimismo, señaló que es necesario reflexionar sobre el papel que desempeñan los "},{type:b,tag:e,props:{},children:[{type:a,value:f}]},{type:a,value:" en el contexto sociopolítico de la región. \"La erosión democrática es un tema que debemos de atender de manera conjunta como "},{type:b,tag:e,props:{},children:[{type:a,value:f}]},{type:a,value:", ya que, independientemente de nuestros temas de interés, es algo que nos afecta a todos\", dijo. En este sentido, enfatizó la necesidad de trabajar de manera coordinada en una red de apoyo transnacional para resolver problemáticas comunes."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Mientras tanto, Dalia Toledo abordó el tema de la corrupción en el fenómeno migratorio. “Cuando hablamos de migración y corrupción, indicó, hay dos maneras en las que podemos relacionar ambos fenómenos: en primer lugar, la corrupción como causa de la migración, es decir, la falta de confianza en las autoridades y de oportunidades debido a la corrupción hacen que la gente quiera migrar, y en segundo lugar, los migrantes como víctimas de corrupción en el camino a su destino final”."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Para desarrollar políticas públicas que atiendan la raíz del problema, expresó, es necesario saber qué tipo de migración se ve afectada (de entrada, tránsito o salida), las características que hacen a la población migrante más vulnerable a la corrupción, el tipo de corrupción prevalece, entre otros aspectos."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"En el evento también hubo representantes de "},{type:b,tag:e,props:{},children:[{type:a,value:f}]},{type:a,value:" de Costa Rica, Guatemala, Honduras, Panamá y El Salvador."}]}]},dir:"\u002Feventos",path:"\u002Feventos\u002Fes_necesario_que_los_think_tanks_de_la_region_trabajen_de_manera_coordinada_para_atender_problematicas_comunes",extension:".md",createdAt:l,updatedAt:l}}],fetch:{},mutations:[]}}("text","element","p","\n","em","think tanks","a","nofollow","noopener","noreferrer","_blank","2023-12-09T02:06:39.560Z")));